        subprocess.run(['gcloud','storage','rsync',str(local),'gs://strange-reducer-509621-e8-matlab-glop-cmp/diagnostics/matlab-storage-smoke-20261005-205327'+'/'+name,'--recursive','--checksums-only'],check=True)
